	var n int
	var err error
	if len(m) == 3 {
		n, err = fmt.Sscanf(m, "%01x%01x%01x", &r, &g, &b)
	} else {
		n, err = fmt.Sscanf(m, "%02x%02x%02x", &r, &g, &b)
	}
	return n==3 && err==nil
}

func actual(m string) bool {
	cmd := exec.Command("./executable", "-m", m, "/nonexistent")
	out, _ := cmd.CombinedOutput()
	// check stderr? Actually need separate
	// Use Output with stderr capture
	// Simpler: run and check exit code and stderr
	// We'll use Command with Stderr pipe
	return false
}
func main() {
	tests := []string{"", "0","00","000","zzz","abz","0000","FFFF","abcd","00000","FFFFF","abcde","0000g","ggggg","F FFF","FF FF","FFF F","FF FFF","FF  FF","F  FFF"," FFFFF","  FFFF","FFFFF ","FFFF  ","a b c","ab cde","   abc   ","ab\tcde","abcdefg","abcdegf","abczdef","zabcdef","00000g","00000gg","000000g","FFFFFFG","FFFFFG","FFFFGG","FFFggg","12345z","1234z5","     "," ","  ","FFF","FFFFFF","0000000","00000000","gggggg","GGGGGG","FFFggg","a b c d e f","a!cde","ab  cde"}
	mismatch:=0
	for _, m := range tests {
		pred := predicted(m)
		// get actual via exec
		cmd := exec.Command("./executable", "-m", m, "/nonexistent")
		// capture stderr
		stderr, _ := cmd.CombinedOutput()
		// Actually CombinedOutput merges stdout+stderr, need to distinguish
		// We'll check if output contains "open /nonexistent"
		s := string(stderr)
		act := false
		// if contains "open /nonexistent" then matte passed
		if contains(s, "open /nonexistent") {
			act = true
		} else if contains(s, "is not a hex-color") {
			act = false
		} else {
			fmt.Printf("UNKNOWN for %q: %q\n", m, s[:200])
			continue
		}
		match := "OK"
		if pred != act {
			match = "MISMATCH"
			mismatch++
		}
		fmt.Printf("m=%q pred=%v act=%v %s\n", m, pred, act, match)
	}
	fmt.Printf("mismatches=%d\n", mismatch)
}
func contains(s, sub string) bool {
	return len(s) >= len(sub) && (func() bool {
		for i:=0;i<=len(s)-len(sub);i++ { if s[i:i+len(sub)]==sub { return true } }
		return false
	})()
}
