	img:=image.NewNRGBA(image.Rect(0,0,2,2))
	img.Set(0,0,color.NRGBA{255,0,0,255})
	img.Set(1,0,color.NRGBA{0,255,0,128})
	img.Set(0,1,color.NRGBA{0,0,0,0})
	img.Set(1,1,color.NRGBA{0,0,255,255})
	f,_:=os.Create("/tmp/trans2x2.png")
	png.Encode(f,img)
	f.Close()
	// 4x4 with checker transparency for classic test (need 4x4 for tc4 tr2)
	img2:=image.NewNRGBA(image.Rect(0,0,4,4))
	for y:=0;y<4;y++ { for x:=0;x<4;x++ {
		if (x+y)%2==0 { img2.Set(x,y,color.NRGBA{255,0,0,255}) } else { img2.Set(x,y,color.NRGBA{0,0,0,0}) }
	} }
	f2,_:=os.Create("/tmp/trans4x4.png")
	png.Encode(f2,img2)
	f2.Close()
	println("done")
}
