package main

import (
	"fmt"
	"math"
)

func sinc(x float64) float64 {
	if x==0 { return 1 }
	return math.Sin(math.Pi*x)/(math.Pi*x)
}
func lanczos(x float64, a int) float64 {
	if math.Abs(x) >= float64(a) { return 0 }
	return sinc(x)*sinc(x/float64(a))
}

func scale1D(src []float64, dstSize int, a int) []float64 {
	srcSize:=len(src)
	scale:=float64(srcSize)/float64(dstSize)
	dst:=make([]float64, dstSize)
	for d:=0; d<dstSize; d++ {
		// center mapping: srcPos = (d+0.5)*scale -0.5
		srcPos:=(float64(d)+0.5)*scale -0.5
		var sum, wsum float64
		// kernel radius a
		for s:=int(math.Floor(srcPos))-a+1; s<=int(math.Floor(srcPos))+a; s++ {
			// clamp or wrap? try clamp
			ss:=s
			if ss<0 { ss=0 } else if ss>=srcSize { ss=srcSize-1 }
			w:=lanczos(srcPos-float64(s), a)
			sum+=src[ss]*w
			wsum+=w
		}
		if wsum!=0 { sum/=wsum }
		dst[d]=sum
	}
	return dst
}

func main() {
	// Test 2->4 with [0,255]
	src:=[]float64{0,255}
	for _,a := range []int{2,3} {
		dst:=scale1D(src,4,a)
		fmt.Printf("a=%d 2->4: %v\n",a,dst)
	}
	// Test 4->8 with [0,85,170,255]
	src2:=[]float64{0,85,170,255}
	for _,a := range []int{2,3} {
		dst:=scale1D(src2,8,a)
		fmt.Printf("a=%d 4->8: %v\n",a,dst)
	}
	// Test 4->4 same size
	src3:=[]float64{0,85,170,255}
	for _,a := range []int{2,3} {
		dst:=scale1D(src3,4,a)
		fmt.Printf("a=%d 4->4: %v\n",a,dst)
	}
}
