package main

import (
	"fmt"
	"math"
)
func sinc(x float64) float64 {
	if x==0 { return 1 }
	return math.Sin(math.Pi*x)/(math.Pi*x)
}
func lanczos(x float64, a int) float64 {
	if math.Abs(x) >= float64(a) { return 0 }
	return sinc(x)*sinc(x/float64(a))
}
func scaleBroad(src []float64, dstSize int, a int) []float64 {
	srcSize:=len(src)
	scale:=float64(srcSize)/float64(dstSize)
	dst:=make([]float64, dstSize)
	for d:=0; d<dstSize; d++ {
		srcPos:=(float64(d)+0.5)*scale -0.5
		var sum, wsum float64
		// For downscale (scale>1), broaden kernel by scale
		effA:=float64(a)
		if scale>1 {
			effA=float64(a)*scale
		}
		for s:=int(math.Ceil(srcPos-effA)); s<=int(math.Floor(srcPos+effA)); s++ {
			ss:=s
			if ss<0 { ss=0 } else if ss>=srcSize { ss=srcSize-1 }
			var w float64
			if scale>1 {
				w=lanczos((srcPos-float64(s))/scale, a)/scale
			} else {
				w=lanczos(srcPos-float64(s), a)
			}
			sum+=src[ss]*w
			wsum+=w
		}
		if wsum!=0 { sum/=wsum }
		if sum<0 { sum=0 } else if sum>255 { sum=255 }
		dst[d]=sum
	}
	return dst
}
func main() {
	src:=make([]float64,80)
	for i:=0;i<80;i++ { src[i]=float64(i*255/79) }
	fmt.Printf("broad lanczos3 80->40: %v\n", scaleBroad(src,40,3)[:10])
	src2:=[]float64{0,85,170,255}
	fmt.Printf("broad lanczos3 4->8: %v\n", scaleBroad(src2,8,3)[:8])
}
