func getTermSize() (int, int, bool) {
	// use ioctl TIOCGWINSZ on stdout
	type winsize struct {
		Row, Col, X, Y uint16
	}
	ws := &winsize{}
	// SYS_IOCTL, TIOCGWINSZ
	// Use syscall.Syscall with SYS_IOCTL
	ret, _, _ := syscall.Syscall(syscall.SYS_IOCTL, uintptr(os.Stdout.Fd()), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
	if int(ret) == -1 {
		return 0, 0, false
	}
	return int(ws.Col), int(ws.Row), true
}

func loadImage(path string) (image.Image, error) {
	if strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://") {
		resp, err := http.Get(path)
		if err != nil {
			return nil, err
		}
		defer resp.Body.Close()
		if resp.StatusCode != 200 {
			return nil, fmt.Errorf("ANSImage: image download failed")
		}
		img, _, err := image.Decode(resp.Body)
		if err != nil {
			return nil, err
		}
		return img, nil
	}
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	img, _, err := image.Decode(f)
	if err != nil {
		return nil, err
	}
	return img, nil
}
