// --- rendering ---

func compositeWithMatte(img image.Image, matteR, matteG, matteB uint8) *image.RGBA {
	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	out := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			c := color.NRGBAModel.Convert(img.At(b.Min.X+x, b.Min.Y+y)).(color.NRGBA)
			if c.A == 255 {
				out.SetRGBA(x, y, color.RGBA{c.R, c.G, c.B, 255})
			} else if c.A == 0 {
				out.SetRGBA(x, y, color.RGBA{matteR, matteG, matteB, 255})
			} else {
				a := uint32(c.A)
				ia := uint32(255 - c.A)
				r := uint8((uint32(c.R)*a + uint32(matteR)*ia) / 255)
				g := uint8((uint32(c.G)*a + uint32(matteG)*ia) / 255)
				bl := uint8((uint32(c.B)*a + uint32(matteB)*ia) / 255)
				out.SetRGBA(x, y, color.RGBA{r, g, bl, 255})
			}
		}
	}
	return out
}

