// dithering helpers
func brightnessMax(r, g, b uint8) uint8 {
	m := r
	if g > m {
		m = g
	}
	if b > m {
		m = b
	}
	return m
}

var blockChars = []string{" ", "░", "▒", "▓", "█"}
var charChars = []string{" ", ".", ":", ";", "+", "=", "x", "X", "$", "&", "#"}

func blockCharForBrightness(v uint8) string {
	// thresholds 48,100,152,204 (upper bounds) => 0:0-48,1:49-100,2:101-152,3:153-204,4:205-255
	if v <= 48 {
		return blockChars[0]
	} else if v <= 100 {
		return blockChars[1]
	} else if v <= 152 {
		return blockChars[2]
	} else if v <= 204 {
		return blockChars[3]
	}
	return blockChars[4]
}

func charCharForBrightness(v uint8) string {
	// thresholds 23,46,69,92,115,138,161,184,207,230
	if v <= 23 {
		return charChars[0]
	} else if v <= 46 {
		return charChars[1]
	} else if v <= 69 {
		return charChars[2]
	} else if v <= 92 {
		return charChars[3]
	} else if v <= 115 {
		return charChars[4]
	} else if v <= 138 {
		return charChars[5]
	} else if v <= 161 {
		return charChars[6]
	} else if v <= 184 {
		return charChars[7]
	} else if v <= 207 {
		return charChars[8]
	} else if v <= 230 {
		return charChars[9]
	}
	return charChars[10]
}

func renderClassic(scaled *image.RGBA, goCode bool) string {
	w := scaled.Bounds().Dx()
	h := scaled.Bounds().Dy()
	// h should be even? For classic, h = rows*2. If h odd? Should not happen for s0/s1 (rows*2 even). For fit, h = (srcH/2-1)*2 = srcH-2 (even when srcH even, odd? For srcH odd, e.g., 5 => dstH=2 (1*2) even. Good. For srcH even, dstH even. Good. So h even. For safety, if h odd, handle last row?
	var sb strings.Builder
	rows := h / 2
	for y := 0; y < rows; y++ {
		var rowSb strings.Builder
		for x := 0; x < w; x++ {
			top := scaled.RGBAAt(x, y*2)
			bot := scaled.RGBAAt(x, y*2+1)
			// bg=top, fg=bot, char lower half block
			rowSb.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm\xe2\x96\x84", top.R, top.G, top.B, bot.R, bot.G, bot.B))
		}
		rowSb.WriteString("\x1b[0m\n")
		rowStr := rowSb.String()
		if goCode {
			// escape for Go string: ESC=>\033, "=>\", \=>\\, newline? Actually rowStr ends with \n (0x0a) which should be escaped as \n (2 chars), ESCs as \033, others raw (including UTF-8 blocks)
			esc := strings.ReplaceAll(rowStr, "\\", "\\\\")
			esc = strings.ReplaceAll(esc, "\"", "\\\"")
			esc = strings.ReplaceAll(esc, "\x1b", "\\033")
			// rowStr ends with \n (real newline). After replacing \x1b, the trailing \n (0x0a) should become \n (2 chars). But strings.ReplaceAll for "\n" (real newline) to "\\n"? Actually rowStr contains real newline 0x0a at end. Replace it with \n (2 chars: \,n)
			esc = strings.ReplaceAll(esc, "\n", "\\n")
			sb.WriteString(fmt.Sprintf("fmt.Print(\"%s\")\n", esc))
		} else {
			sb.WriteString(rowStr)
		}
	}
	return sb.String()
}

func renderDither(scaled *image.RGBA, matteR, matteG, matteB uint8, nobg bool, useChars bool, goCode bool) string {
	w := scaled.Bounds().Dx()
	h := scaled.Bounds().Dy()
	var sb strings.Builder
	for y := 0; y < h; y++ {
		var rowSb strings.Builder
		for x := 0; x < w; x++ {
			c := scaled.RGBAAt(x, y)
			v := brightnessMax(c.R, c.G, c.B)
			var ch string
			if useChars {
				ch = charCharForBrightness(v)
			} else {
				ch = blockCharForBrightness(v)
			}
			if nobg {
				rowSb.WriteString(fmt.Sprintf("\x1b[38;2;%d;%d;%dm%s", c.R, c.G, c.B, ch))
			} else {
				rowSb.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm%s", matteR, matteG, matteB, c.R, c.G, c.B, ch))
			}
		}
		rowSb.WriteString("\x1b[0m\n")
		rowStr := rowSb.String()
		if goCode {
			esc := strings.ReplaceAll(rowStr, "\\", "\\\\")
			esc = strings.ReplaceAll(esc, "\"", "\\\"")
			esc = strings.ReplaceAll(esc, "\x1b", "\\033")
			esc = strings.ReplaceAll(esc, "\n", "\\n")
			sb.WriteString(fmt.Sprintf("fmt.Print(\"%s\")\n", esc))
		} else {
			sb.WriteString(rowStr)
		}
	}
	return sb.String()
}

func fillCrop(src *image.RGBA, dstW, dstH int) *image.RGBA {
	// scale src to fill dst preserving aspect, center-crop to dst
	srcW := src.Bounds().Dx()
	srcH := src.Bounds().Dy()
	scaleW := float64(dstW) / float64(srcW)
	scaleH := float64(dstH) / float64(srcH)
	scale := scaleW
	if scaleH > scaleW {
		scale = scaleH
	}
	tmpW := int(math.Round(float64(srcW) * scale))
	tmpH := int(math.Round(float64(srcH) * scale))
	if tmpW < 1 {
		tmpW = 1
	}
	if tmpH < 1 {
		tmpH = 1
	}
	tmp := scaleRGBA(src, tmpW, tmpH)
	// center crop to dstW x dstH
	out := image.NewRGBA(image.Rect(0, 0, dstW, dstH))
	ox := (tmpW - dstW) / 2
	oy := (tmpH - dstH) / 2
	if ox < 0 {
		ox = 0
	}
	if oy < 0 {
		oy = 0
	}
	for y := 0; y < dstH; y++ {
		for x := 0; x < dstW; x++ {
			out.SetRGBA(x, y, tmp.RGBAAt(ox+x, oy+y))
		}
	}
	return out
}

