func fillCrop(src *image.RGBA, dstW, dstH int) *image.RGBA {
	// scale src to fill dst preserving aspect, center-crop to dst
	srcW := src.Bounds().Dx()
	srcH := src.Bounds().Dy()
	scaleW := float64(dstW) / float64(srcW)
	scaleH := float64(dstH) / float64(srcH)
	scale := scaleW
	if scaleH > scaleW {
		scale = scaleH
	}
	tmpW := int(math.Round(float64(srcW) * scale))
	tmpH := int(math.Round(float64(srcH) * scale))
	if tmpW < 1 {
		tmpW = 1
	}
	if tmpH < 1 {
		tmpH = 1
	}
	tmp := scaleRGBA(src, tmpW, tmpH)
	// center crop to dstW x dstH
	out := image.NewRGBA(image.Rect(0, 0, dstW, dstH))
	ox := (tmpW - dstW) / 2
	oy := (tmpH - dstH) / 2
	if ox < 0 {
		ox = 0
	}
	if oy < 0 {
		oy = 0
	}
	for y := 0; y < dstH; y++ {
		for x := 0; x < dstW; x++ {
			out.SetRGBA(x, y, tmp.RGBAAt(ox+x, oy+y))
		}
	}
	return out
}

