func renderImage(img image.Image, cols, rows, d, s int, matteR, matteG, matteB uint8, goCode, nobg bool) (string, error) {
	srcW := img.Bounds().Dx()
	srcH := img.Bounds().Dy()
	// composite with matte to get opaque RGBA for scaling
	opaque := compositeWithMatte(img, matteR, matteG, matteB)
	if s == 2 {
		// fit, buggy, ignores terminal, based solely on src
		if d == 0 {
			// classic fit: check src dimensions >=2
			if srcW < 2 || srcH < 2 {
				return "", fmt.Errorf("ANSImage: height or width must be >=2")
			}
			dstCols := srcW
			dstRowsTerm := srcH/2 - 1
			if dstRowsTerm == 0 {
				// empty, no error, 0 bytes
				return "", nil
			}
			if dstRowsTerm < 0 {
				// should not happen since srcH>=2 => srcH/2>=1 => dstRows>=0. For srcH=2, dstRows=0 => empty. For srcH=3, dstRows=0 => empty. Good. Negative only if srcH==1? Already error. So no negative.
				return "", fmt.Errorf("ANSImage: height or width must be >=2")
			}
			dstW := dstCols
			dstH := dstRowsTerm * 2
			scaled := scaleRGBA(opaque, dstW, dstH)
			return renderClassic(scaled, goCode), nil
		} else {
			// dither fit: dstW=srcW/4, dstH=srcH/8-1 (pixel, same as terminal for dither since 1px per cell)
			dstW := srcW / 4
			dstH := srcH/8 - 1
			// Actually srcH/8 integer division trunc, then -1. For srcH<8, srcH/8==0 => dstH==-1 => error. Good.
			if dstW < 2 || dstH <= 0 {
				// dstW<2 (0 or1) => error, dstH<=0 (0 or negative) => error. Note dstH==1 allowed (since >0). Good. This matches observed: 5x1 success (dstW=5>=2, dstH=1>0), 2x0 (dstW=2>=2, dstH=0<=0 => error), 1x1 (dstW=1<2 => error).
				return "", fmt.Errorf("ANSImage: height or width must be >=2")
			}
			scaled := scaleRGBA(opaque, dstW, dstH)
			if d == 1 {
				return renderDither(scaled, matteR, matteG, matteB, nobg, false, goCode), nil
			} else {
				return renderDither(scaled, matteR, matteG, matteB, nobg, true, goCode), nil
			}
		}
	}
	// s==0 or 1: terminal-based
	var dstW, dstH int
	if d == 0 {
		dstW = cols
		dstH = rows * 2
	} else {
		dstW = cols
		dstH = rows
	}
	var scaled *image.RGBA
	if s == 0 {
		// resize, stretch directly to dst
		scaled = scaleRGBA(opaque, dstW, dstH)
	} else {
		// s==1 fill: scale to fill dst preserving aspect, center-crop to dst
		scaled = fillCrop(opaque, dstW, dstH)
	}
	if d == 0 {
		return renderClassic(scaled, goCode), nil
	} else if d == 1 {
		return renderDither(scaled, matteR, matteG, matteB, nobg, false, goCode), nil
	} else {
		return renderDither(scaled, matteR, matteG, matteB, nobg, true, goCode), nil
	}
}
